const fs = require('node:fs/promises');
const path = require('node:path');

async function generateDeployScript(rootDir) {
  const templatePath = path.join(rootDir, 'scripts', 'deploy-sftp.template.js');
  const outputPath = path.join(rootDir, 'scripts', 'deploy-sftp.generated.js');
  const template = await fs.readFile(templatePath, 'utf8');

  const generated = [
    '#!/usr/bin/env node',
    '// Generated by scripts/generate-deploy-script.js. Do not edit directly.',
    '',
    template
  ].join('\n');

  await fs.writeFile(outputPath, generated, 'utf8');

  try {
    await fs.chmod(outputPath, 0o755);
  } catch (_error) {
    // Ignore chmod issues on platforms that do not support POSIX modes.
  }

  return outputPath;
}

if (require.main === module) {
  const rootDir = process.cwd();
  generateDeployScript(rootDir)
    .then(outputPath => {
      console.log(`Generated deploy script: ${path.relative(rootDir, outputPath).replace(/\\/g, '/')}`);
    })
    .catch(error => {
      console.error(error.message);
      process.exit(1);
    });
}

module.exports = {
  generateDeployScript
};
